'use strict';
let data, page='wallet', period='FY2026', unit=1000, report='income', backend=false;
const state={growth:0,margin:0,days:0,capex:0,borrowing:0};
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>(n<0?'−':'')+'$'+(Math.abs(n)/unit).toLocaleString('en-US',{minimumFractionDigits:unit===1000?2:0,maximumFractionDigits:unit===1000?2:0})+(unit===1000?'B':'M');
const pct=n=>(n*100).toFixed(1)+'%';
const v=()=>data.periods.find(p=>p.id===period).values;
const label=k=>data.metrics.find(m=>m.code===k)?.label||k;
function storeRead(k,fallback){try{return JSON.parse(localStorage.getItem(k))||fallback}catch{return fallback}}
function storeWrite(k,value){try{localStorage.setItem(k,JSON.stringify(value));return true}catch{toast('Browser storage unavailable. Export to keep your work.');return false}}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3500)}
function delta(k){if(period==='FY2025')return '<small>Prior-year comparison unavailable</small>';const old=data.periods[0].values[k],d=(v()[k]-old)/Math.abs(old);return `<span class="delta ${d<0?'negative':''}">${d>=0?'+':''}${pct(d)} <small>vs FY2025</small></span>`}
function metric(k,name){return `<button class="card metric-button" data-detail="${k}"><div class="card-label">${name||label(k)} <span>↗</span></div><div class="big-number">${money(v()[k])}</div>${delta(k)}</button>`}
function tiny(name,value,key,foot){return `<button class="card metric-button submetric" data-detail="${key}"><span class="card-label">${name} <span>↗</span></span><strong>${value}</strong><small>${foot}</small></button>`}
function nav(p){page=['wallet','performance','simulator','reports'].includes(p)?p:'wallet';location.hash=page;render()}
function render(){
const headings={wallet:['FINANCIAL COMMAND CENTRE','Your company. In view.','Liquidity, performance and decisions. Connected.'],performance:['BEHIND THE NUMBERS','Performance, unpacked.','Trace growth, profitability and the cash behind earnings.'],simulator:['EXPLORE THE POSSIBILITIES','What happens if…','Move the levers. See the cash impact. Save a scenario.'],reports:['FROM NUMBERS TO NARRATIVE','Your reporting workspace.','Comparative statements, source evidence and IFRS review notes.']};
const h=headings[page];$('#eyebrow').textContent=h[0];$('#title').textContent=h[1];$('#subtitle').textContent=h[2];$('#crumb').textContent=page[0].toUpperCase()+page.slice(1);$$('nav button').forEach(b=>{b.classList.toggle('active',b.dataset.page===page);b.setAttribute('aria-current',b.dataset.page===page?'page':'false')});$('#financial-tape').innerHTML=Array(2).fill(['revenue','gross','net','cfo','cash'].map(k=>`<span>${label(k)} <b>${money(v()[k])}</b><em>${period}</em></span>`).join('')).join('');$('#date-label').textContent=`${period} · Year ended ${data.periods.find(p=>p.id===period).end_date}`;
$('#content').innerHTML=({wallet:wallet,performance:performance,simulator:simulator,reports:reports})[page]();bind();if(page==='simulator'){updateSimulation();loadSaved()}
}
function wallet(){const x=v(),debt=x.debt_current+x.debt_long,share=x.cash/x.liquidity;
return `<section class="wallet-top" aria-label="Financial wallet"><button class="card wallet-card" data-detail="liquidity"><div class="card-label"><span>Total liquid assets</span><b>↗</b></div><div class="big-number">${money(x.liquidity)}</div><small>Cash + current marketable securities</small><div class="wallet-card-bottom"><span>NVIDIA CORPORATION</span><b>${period} / USD</b></div></button>${metric('cash','Cash & equivalents')}${metric('securities','Current investments')}</section><section class="submetrics" aria-label="Key metrics">${tiny('Financial debt',money(debt),'debt','Current + non-current borrowings')}${tiny('Net liquid assets',money(x.liquidity-debt),'net_liquid','Liquid assets less financial debt')}${tiny('Free cash flow',money(x.cfo-x.capex-x.capex_principal),'fcf','Non-GAAP · annual cash generation')}${tiny('Current ratio',(x.current_assets/x.current_liabilities).toFixed(2)+'×','ratio','Current assets ÷ current liabilities')}</section><div class="two-cols"><section class="card"><div class="panel-head"><div><h2>Follow the cash</h2><small>From opening balance to closing cash · ${period}</small></div><button class="text-button" data-goto="reports" data-report="cashflow">View statement ↗</button></div>${waterfall(x)}<div class="legend"><span>Cash balance / operating</span><span>Investing</span><span>Financing</span></div></section><section class="card"><div class="panel-head"><h2>Inside the wallet</h2><button class="text-button" data-detail="liquidity">Details ↗</button></div><div class="allocation"><div class="donut" style="background:conic-gradient(var(--lime) 0 ${share*100}%,var(--purple) ${share*100}% 100%)"><span>Liquid<br>assets</span></div><div class="allocation-list"><div class="allocation-row"><span>Cash</span><b>${pct(share)}</b></div><div class="allocation-row"><span>Investments</span><b>${pct(1-share)}</b></div><div class="allocation-row"><span>Total</span><b>${money(x.liquidity)}</b></div></div></div><div class="insight"><strong>${money(x.cfo)} generated by operations.</strong> After investing and financing, cash changed by ${money(x.cash_change)} during ${period}.</div><p class="note">Marketable securities are investments, not cash equivalents. Net liquid assets exclude lease liabilities.</p></section></div><div class="strip"><div><h3>Take control of the next move.</h3><p>Test a decision against NVIDIA’s reported financials.</p></div><div class="quick-actions"><button class="button danger" data-quick="stress">Liquidity stress test ↗</button><button class="button cyan" data-quick="growth">Model capital spend ↗</button></div></div>`}
function waterfall(x){const a=[['Opening',0,x.opening_cash,'var(--green)'],['Operating',x.opening_cash,x.opening_cash+x.cfo,'var(--lime)'],['Investing',x.opening_cash+x.cfo,x.opening_cash+x.cfo+x.cfi,'var(--purple)'],['Financing',x.opening_cash+x.cfo+x.cfi,x.cash,'var(--red)'],['Closing',0,x.cash,'var(--green)']];const max=Math.max(...a.flatMap(r=>[r[1],r[2]]))*1.17,H=205,Y=z=>225-z/max*H;let svg=`<svg class="chart" viewBox="0 0 620 285" role="img" aria-label="Cash bridge: opening ${x.opening_cash}, operating ${x.cfo}, investing ${x.cfi}, financing ${x.cff}, closing ${x.cash}; USD millions"><line x1="20" x2="610" y1="225" y2="225" stroke="#39443c"/>`;a.forEach((r,i)=>{const left=28+i*121,top=Y(Math.max(r[1],r[2])),height=Math.max(4,Math.abs(Y(r[1])-Y(r[2])));svg+=`<rect x="${left}" y="${top}" width="76" height="${height}" rx="4" fill="${r[3]}"/><text class="value" x="${left+38}" y="${top-10}" text-anchor="middle">${money(i===0?x.opening_cash:i===4?x.cash:r[2]-r[1])}</text><text x="${left+38}" y="255" text-anchor="middle">${r[0]}</text>`;if(i<4)svg+=`<line x1="${left+76}" x2="${left+121}" y1="${Y(r[2])}" y2="${Y(r[2])}" stroke="#566257" stroke-dasharray="4 4"/>`});return svg+'</svg>'}
function performance(){const x=v(),old=data.periods[0].values,now=data.periods[1].values;return `<div class="compare-cards">${metric('revenue')}${metric('operating')}${metric('net')}</div><div class="two-cols"><section class="card"><div class="panel-head"><div><h2>Two years. One clear direction.</h2><small>Annual reported results · comparison always shows both years</small></div></div><div class="comparison">${['revenue','operating','net'].map(k=>`<div class="bar-group"><div class="bar old" style="height:${old[k]/now.revenue*85}%"><span>${money(old[k])}</span></div><div class="bar" style="height:${now[k]/now.revenue*85}%"><span>${money(now[k])}</span></div><label>${k==='revenue'?'Revenue':k==='operating'?'Operating profit':'Net profit'}</label></div>`).join('')}</div><div class="legend"><span>FY2026</span><span>FY2025</span></div></section><section class="card"><div class="panel-head"><h2>Earnings quality · ${period}</h2></div>${[['Gross margin',pct(x.gross/x.revenue)],['Operating margin',pct(x.operating/x.revenue)],['Net margin',pct(x.net/x.revenue)],['Operating cash / net profit',(x.cfo/x.net).toFixed(2)+'×'],['Free cash flow / revenue',pct((x.cfo-x.capex-x.capex_principal)/x.revenue)]].map(([l,n])=>`<div class="allocation-row"><span>${l}</span><b>${n}</b></div>`).join('')}<p class="note">Margins use GAAP income. Free cash flow is a separately defined non-GAAP cash measure.</p></section></div><section class="card performance-chart"><div class="panel-head"><div><h2>Why profit and cash differ</h2><small>Indirect operating cash reconciliation · ${period}</small></div></div>${statementTable(['net','sbc','da','gains','cf_tax','cf_other','cf_ar','cf_inventory','cf_prepaid','cf_ap','cf_accrued','cf_long','cfo'])}<div class="checks">✓ Reconciles to reported operating cash flow</div></section>`}
const sliders=[['growth','Revenue growth',-30,50,1,'%','Relative to selected annual revenue'],['margin','Gross margin change',-15,10,.5,' pp','Percentage-point change; operating expenses held fixed'],['days','Additional collection delay',0,90,1,' days','Cash tied up in receivables; 365-day convention'],['capex','Additional capital spending',0,30,.5,'B','USD billions; cash paid during the modeled year'],['borrowing','Additional borrowing',0,30,.5,'B','USD billions; no incremental interest modeled']];
function simulator(){return `<div class="sim-grid"><section class="card"><h2>Build your scenario</h2><div class="preset-row"><button class="button" data-preset="base">Baseline</button><button class="button" data-preset="growth">Expansion</button><button class="button" data-preset="stress">Cash squeeze</button></div>${sliders.map(([k,l,min,max,step,suffix,help])=>`<div class="slider-field"><label for="${k}">${l}<output id="out-${k}">${state[k]}${suffix}</output></label><input type="range" id="${k}" min="${min}" max="${max}" step="${step}" value="${state[k]}"><small>${help}</small></div>`).join('')}<div class="actions"><button class="button light" id="save-scenario">${backend?'Save scenario':'Keep draft'}</button><button class="button" id="export-scenario">Export CSV</button></div></section><div><section class="card sim-result"><div class="card-label">Modeled closing cash <span class="badge">12-MONTH SCENARIO</span></div><div class="big-number" id="sim-cash"></div><p id="sim-change"></p><div class="sim-summary"><div><small>Operating cash flow</small><strong id="sim-cfo"></strong></div><div><small>Free cash flow</small><strong id="sim-fcf"></strong></div><div><small>Financial debt</small><strong id="sim-debt"></strong></div></div></section><section class="card" style="margin-top:20px"><div class="panel-head"><h2>How the cash moves</h2></div><div id="sim-bridge"></div><p class="note" id="sim-warning"></p></section><details class="card" style="margin-top:20px"><summary>Model assumptions & limitations</summary><p class="note">This is a sensitivity exercise, not NVIDIA guidance or a complete three-statement forecast. It starts with selected year-end cash, then repeats that year's annual cash flows with your changes. Securities stay unchanged and are not automatically sold to fund deficits.</p><p class="note">Revenue × adjusted gross margin − fixed operating expenses gives operating profit. Other income and the effective tax rate are held constant; no tax benefit is assumed on losses. Operating cash flow changes by the difference in net profit less extra receivables (modeled revenue ÷ 365 × extra days). All other working-capital and noncash adjustments are fixed. Additional capex affects cash only; no incremental depreciation. New borrowing has no modeled interest or repayment. Baseline investing and financing include historical buybacks and investments.</p></details><section class="card" style="margin-top:20px"><h2>${backend?'Saved scenarios':'Scenario drafts'}</h2><p class="note" id="save-location"></p><div class="saved-list" id="saved"></div></section></div></div>`}
function calculate(x,a){const revenue=x.revenue*(1+a.growth/100),margin=x.gross/x.revenue+a.margin/100,operating=revenue*margin-x.opex,pretax=operating+x.interest_income-x.interest_expense+x.other_income,net=pretax-Math.max(0,pretax)*x.tax/x.pretax,receivables=revenue/365*a.days,cfo=x.cfo+net-x.net-receivables,cfi=x.cfi-a.capex*1000,cff=x.cff+a.borrowing*1000;return {revenue,operating,net,receivables,cfo,cfi,cff,ending_cash:x.cash+cfo+cfi+cff,free_cash_flow:cfo-x.capex-x.capex_principal-a.capex*1000,debt:x.debt_current+x.debt_long+a.borrowing*1000}}
let result;
function updateSimulation(){result=calculate(v(),state);const base=calculate(v(),{growth:0,margin:0,days:0,capex:0,borrowing:0});$('#sim-cash').textContent=money(result.ending_cash);$('#sim-cash').style.color=result.ending_cash<0?'var(--red)':'var(--lime)';$('#sim-change').textContent=`${money(result.ending_cash-base.ending_cash)} versus repeated-year baseline`;$('#sim-cfo').textContent=money(result.cfo);$('#sim-fcf').textContent=money(result.free_cash_flow);$('#sim-debt').textContent=money(result.debt);$('#sim-bridge').innerHTML=[['Opening cash',v().cash],['Operating',result.cfo],['Investing',result.cfi],['Financing',result.cff],['Closing cash',result.ending_cash]].map(([l,n])=>`<div class="allocation-row"><span>${l}</span><b class="${n<0?'negative':''}">${money(n)}</b></div>`).join('');$('#sim-warning').textContent=result.ending_cash<0?'Funding gap: this scenario requires additional financing or asset sales. Negative cash is a shortfall, not an actual bank balance.':`Extra collection delays tie up ${money(result.receivables)} in receivables.`;sliders.forEach(([k,,,,,suffix])=>{$('#out-'+k).textContent=state[k]+suffix})}
async function loadSaved(){let list;if(backend){try{const r=await fetch('/api/scenarios');if(!r.ok)throw Error();list=await r.json()}catch{toast('Unable to load saved scenarios.');list=[]}}else list=storeRead('cw-scenarios',[]);if(page!=='simulator')return;$('#save-location').textContent=backend?'Saved in your local SQLite database.':'Temporary drafts on this device. Export to keep a copy; the Python app saves scenarios in SQLite.';$('#saved').innerHTML=list.length?'':'<small>No scenarios yet.</small>';list.forEach(item=>{const b=document.createElement('button');b.className='button';b.textContent=item.name+' · '+(item.period_id||item.period);b.onclick=()=>{try{const a=typeof item.assumptions==='string'?JSON.parse(item.assumptions):item.assumptions;for(const [k,,lo,hi] of sliders){if(!Number.isFinite(a[k])||a[k]<lo||a[k]>hi)throw Error()}period=item.period_id||item.period;if(!data.periods.some(p=>p.id===period))throw Error();Object.assign(state,a);$('#period').value=period;render();toast('Scenario loaded')}catch{toast('This saved scenario is invalid.')}};$('#saved').append(b)})}
function saveDialog(){showDetail(`<div class="eyebrow">KEEP EXPLORING</div><h2>${backend?'Save this scenario':'Keep a scenario draft'}</h2><p>Keep these assumptions with ${period} as the base year.</p><form id="scenario-form"><label for="scenario-name" style="display:block;margin-top:20px">Scenario name</label><input id="scenario-name" required maxlength="100" value="${escapeHTML('Scenario '+new Date().toLocaleDateString())}" style="width:100%;padding:10px;margin-top:8px;background:#101713;border:1px solid #53624f;color:white;border-radius:7px"><button class="button light" style="margin-top:20px">Save scenario</button></form>`);$('#scenario-form').onsubmit=async e=>{e.preventDefault();const name=$('#scenario-name').value.trim();if(!name)return;const item={name,period,assumptions:{...state}};if(backend){try{const r=await fetch('/api/scenarios',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(item)});if(!r.ok)throw Error()}catch{toast('Save failed. Export your scenario instead.');return}}else{const rows=storeRead('cw-scenarios',[]);rows.unshift(item);if(!storeWrite('cw-scenarios',rows))return}$('#detail').close();toast('Scenario saved');loadSaved()}}
const incomeKeys=['revenue','cost','gross','rd','sga','opex','operating','interest_income','interest_expense','other_income','pretax','tax','net'];
const positionKeys=['cash','securities','ar','inventory','prepaid','current_assets','ppe','lease_assets','goodwill','intangibles','deferred_tax','equity_investments','other_assets','assets','ap','accrued','debt_current','current_liabilities','debt_long','lease_liabilities','other_liabilities','liabilities','equity'];
const cashKeys=['opening_cash','net','sbc','da','gains','cf_tax','cf_other','cf_ar','cf_inventory','cf_prepaid','cf_ap','cf_accrued','cf_long','cfo','cfi','cff','cash_change','cash'];
const totals=['gross','opex','operating','pretax','net','current_assets','assets','current_liabilities','liabilities','equity','cfo','cfi','cff','cash_change','cash'];
function statementTable(keys){const periods=period==='FY2026'?[...data.periods].reverse():[data.periods[0]];return `<div class="table-wrap"><table><thead><tr><th>USD ${unit===1000?'billions':'millions'}</th>${periods.map(p=>`<th>${p.id}</th>`).join('')}${periods.length===2?'<th>Change</th>':''}</tr></thead><tbody>${keys.map(k=>`<tr class="${totals.includes(k)?'total':''}"><td><button class="rowbutton" data-detail="${k}">${label(k)}</button></td>${periods.map(p=>`<td>${money(p.values[k])}</td>`).join('')}${periods.length===2?`<td>${money(periods[0].values[k]-periods[1].values[k])}</td>`:''}</tr>`).join('')}</tbody></table></div>`}
const reviewTopics=[['presentation','IAS 1 / IFRS 18','Presentation, comparatives, material policies, OCI and changes in equity. IFRS 18 applies for annual periods beginning on or after 1 January 2027; earlier application is permitted.','https://www.ifrs.org/issued-standards/list-of-standards/ifrs-18-presentation-and-disclosure-in-financial-statements/'],['cashflow','IAS 7 · Cash flows','Assess cash-equivalent eligibility and interest, dividend and tax classifications under the applicable reporting requirements.','https://www.ifrs.org/issued-standards/list-of-standards/ias-7-statement-of-cash-flows/'],['leases','IFRS 16 · Leases','Review contract-level lease treatment, depreciation, interest, liabilities and cash-flow classifications. Public totals alone do not quantify conversion entries.','https://www.ifrs.org/issued-standards/list-of-standards/ifrs-16-leases/'],['assets','IAS 38 / IFRS 9 · Assets','Review development-cost recognition and investment classification, measurement and impairment. Document evidence and tax effects for each adjustment.','https://www.ifrs.org/issued-standards/list-of-standards/ias-38-intangible-assets/']];
function reports(){return `<div class="report-tabs" aria-label="Report selection">${[['income','Profit & loss'],['position','Financial position'],['cashflow','Cash flows'],['ifrs','IFRS review']].map(([k,l])=>`<button class="button ${report===k?'active':''}" data-report-tab="${k}">${l}</button>`).join('')}</div>${report==='ifrs'?ifrs():`<section class="card"><div class="panel-head"><div><h2>NVIDIA Corporation</h2><small>${{income:'Condensed statement of profit or loss',position:'Condensed statement of financial position',cashflow:'Condensed statement of cash flows'}[report]} · ${period}</small></div><span class="badge">US GAAP</span></div><p class="report-meta">${report==='position'?'As at':'Year ended'} ${data.periods.find(p=>p.id===period).end_date} · Public results released 25 February 2026 · Selected financial information</p>${statementTable(report==='income'?incomeKeys:report==='position'?positionKeys:cashKeys)}<div class="checks">${report==='income'?'✓ Revenue − costs = gross profit · ✓ Profit before tax − tax = net profit':report==='position'?'✓ Assets = liabilities + equity':'✓ Opening cash + operating + investing + financing = closing cash'}</div><p class="note">Source: <a target="_blank" rel="noopener" href="${data.source}">NVIDIA FY2026 public results ↗</a>. The release labels these condensed statements unaudited. Labels are simplified; USD-million source values are retained. This is not a complete IFRS financial statement set.</p><div class="actions"><button class="button light" id="download-report">Download CSV ↓</button><button class="button" id="print-report">Print / Save PDF</button><button class="button" data-report-tab="ifrs">Open IFRS review ↗</button></div></section>`}`}
function ifrs(){const notes=storeRead('cw-ifrs-'+period,{});return `<div class="warning"><strong>IFRS conversion workspace — review required.</strong> NVIDIA's figures remain US GAAP. No conversion adjustments have been assumed. This checklist does not certify compliance; full IFRS reporting needs entity-specific policies, adjustments, comparative information and disclosures.</div><div class="review-grid">${reviewTopics.map(([key,title,description,url])=>`<section class="review-card"><h3>${title}</h3><p>${description}</p><p><a href="${url}" target="_blank" rel="noopener">Standard overview ↗</a></p><label><input type="checkbox" data-review-check="${key}" ${notes[key]?.reviewed?'checked':''}> Reviewed by me</label><label class="sr" for="note-${key}">${title} review notes</label><textarea id="note-${key}" data-review-note="${key}" placeholder="Evidence, proposed adjustment, or outstanding question…">${escapeHTML(notes[key]?.note||'')}</textarea></section>`).join('')}</div><div class="actions"><button class="button light" id="export-review">Export review notes ↓</button></div><p class="note">Draft notes are retained temporarily in this browser for ${period}. “Reviewed” records your workflow only; it does not change the accounting basis or financial figures.</p>`}
function showDetail(html){$('#detail-content').innerHTML=html;$('#detail').showModal()}
function explain(k){const x=v();const custom={debt:['Financial debt',money(x.debt_current+x.debt_long),'Current debt + non-current debt','Lease liabilities are excluded.'],net_liquid:['Net liquid assets',money(x.liquidity-x.debt_current-x.debt_long),'Cash + current marketable securities − financial debt','A derived analytical measure, not a GAAP or IFRS subtotal. Lease liabilities excluded.'],fcf:['Free cash flow',money(x.cfo-x.capex-x.capex_principal),'Operating cash flow − property, equipment & intangible purchases − related principal payments','Uses the definition in NVIDIA’s release. This is a non-GAAP measure.'],ratio:['Current ratio',(x.current_assets/x.current_liabilities).toFixed(2)+'×','Current assets ÷ current liabilities','A liquidity ratio; it is not a measure of cash available to spend.'],liquidity:['Total liquid assets',money(x.liquidity),'Cash & equivalents + current marketable securities','An analytical label for the combined balance reported by NVIDIA. Marketable securities can fluctuate in value.'],securities:['Current marketable securities',money(x.securities),'Reported combined cash / securities balance − cash & equivalents','Derived from the combined balance-sheet line and closing cash in the cash-flow statement.']};const d=custom[k]||[label(k),money(x[k]),'Reported '+period+' amount · USD millions: '+x[k].toLocaleString('en-US'),'Annual public financial information. Not a live bank balance or transaction feed.'];showDetail(`<div class="eyebrow">EXPLAIN THIS NUMBER</div><h2>${d[0]}</h2><div class="big-number">${d[1]}</div><div class="formula">${d[2]}</div><p>${d[3]}</p><p>${period} · Ended ${data.periods.find(p=>p.id===period).end_date} · US GAAP source</p><p><a target="_blank" rel="noopener" href="${data.source}">Open original NVIDIA financial release ↗</a></p>`)}
function csv(rows){return '\ufeff'+rows.map(row=>row.map(val=>{let s=String(val??'');if(typeof val==='string'&&/^[=+@\-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}).join(',')).join('\r\n')}
function download(name,text,type='text/csv;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Download ready')}
function downloadReport(){const keys=report==='income'?incomeKeys:report==='position'?positionKeys:cashKeys;const ps=period==='FY2026'?[...data.periods].reverse():[data.periods[0]];download(`NVIDIA-${period}-${report}.csv`,csv([['Company Wallet · NVIDIA · selected US GAAP financial information'],['Source',data.source],['Source release date','2026-02-25'],['Unit','USD millions'],['Accounting status','Not an IFRS conversion; condensed source statements labelled unaudited'],['Metric',...ps.map(p=>p.id)],...keys.map(k=>[label(k),...ps.map(p=>p.values[k])])]))}
function exportScenario(){download(`NVIDIA-${period}-scenario.csv`,csv([['Company Wallet sensitivity scenario — not guidance'],['Base period',period],['Source',data.source],['Assumptions'],...sliders.map(([k,l,,,,suffix])=>[l,state[k],suffix]),['Results','USD millions'],...Object.entries(result),['Method','Repeat base-year annual flows from closing cash; fixed opex, other income, effective tax rate, other working capital and noncash adjustments. No incremental depreciation, borrowing interest or repayment. No tax benefit on losses. Securities are not liquidated.']]))}
function bind(){
$$('[data-quick]').forEach(b=>b.onclick=()=>{Object.assign(state,{growth:0,margin:0,days:0,capex:0,borrowing:0},b.dataset.quick==='stress'?{growth:-20,margin:-5,days:60,capex:10}:{growth:20,capex:5});nav('simulator')});$$('.chart').forEach(chart=>{chart.onpointermove=e=>{if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const r=chart.getBoundingClientRect();chart.style.setProperty('--px',(e.clientX-r.left)+'px');chart.style.setProperty('--py',(e.clientY-r.top)+'px');chart.classList.add('tracking')};chart.onpointerleave=()=>chart.classList.remove('tracking')});$$('[data-detail]').forEach(b=>b.onclick=()=>explain(b.dataset.detail));$$('[data-goto]').forEach(b=>b.onclick=()=>{if(b.dataset.report)report=b.dataset.report;nav(b.dataset.goto)});$$('[data-report-tab]').forEach(b=>b.onclick=()=>{report=b.dataset.reportTab;render()});
if(page==='simulator'){sliders.forEach(([k])=>$('#'+k).oninput=e=>{state[k]=Number(e.target.value);updateSimulation()});$$('[data-preset]').forEach(b=>b.onclick=()=>{Object.assign(state,{growth:0,margin:0,days:0,capex:0,borrowing:0},b.dataset.preset==='growth'?{growth:20,capex:5}:b.dataset.preset==='stress'?{growth:-20,margin:-5,days:60,capex:10}:{});render()});$('#save-scenario').onclick=saveDialog;$('#export-scenario').onclick=exportScenario}
if($('#download-report'))$('#download-report').onclick=downloadReport;if($('#print-report'))$('#print-report').onclick=()=>window.print();
if(report==='ifrs'&&page==='reports'){const save=()=>{const a={};reviewTopics.forEach(([k])=>a[k]={reviewed:$(`[data-review-check="${k}"]`).checked,note:$(`[data-review-note="${k}"]`).value});storeWrite('cw-ifrs-'+period,a)};$$('[data-review-check]').forEach(e=>e.onchange=save);$$('[data-review-note]').forEach(e=>e.oninput=save);$('#export-review').onclick=()=>{const a=storeRead('cw-ifrs-'+period,{});download(`NVIDIA-${period}-IFRS-review.csv`,csv([['IFRS review worksheet — no conversion adjustments applied'],['Base period',period],['Source basis','US GAAP'],['Topic','Reviewed by user','Notes'],...reviewTopics.map(([k,t])=>[t,!!a[k]?.reviewed,a[k]?.note||''])]))}}
}
async function init(){try{try{const r=await fetch('/api/data');if(!r.ok||!r.headers.get('content-type')?.includes('application/json'))throw Error();data=await r.json();if(!data.periods)throw Error();backend=true}catch{const r=await fetch('data.json');if(!r.ok)throw Error('Snapshot unavailable');data=await r.json()};$('#runtime').textContent=backend?'Python + SQLite connected':'Browser demo · Python + SQLite version available separately';$$('nav button').forEach(b=>b.onclick=()=>nav(b.dataset.page));$('#period').onchange=e=>{period=e.target.value;render()};$('#units').onchange=e=>{unit=Number(e.target.value);render()};$('#report-shortcut').onclick=()=>{report='income';nav('reports')};$('.close').onclick=()=>$('#detail').close();$('#detail').onclick=e=>{if(e.target===$('#detail'))$('#detail').close()};window.onhashchange=()=>{const p=location.hash.slice(1);if(p!==page){page=['wallet','performance','simulator','reports'].includes(p)?p:'wallet';render()}};page=['wallet','performance','simulator','reports'].includes(location.hash.slice(1))?location.hash.slice(1):'wallet';render()}catch(e){$('#content').innerHTML='<div class="warning">Financial data could not be loaded. Please reload the page or restart the Python app.</div>'}}
init();
// Optional browser agent integration, using the same model and visible controls.
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();
 Promise.resolve(document.modelContext.registerTool({
  name:'configure_cash_scenario',title:'Configure cash scenario',description:'Set a NVIDIA annual base period and sensitivity assumptions, open the simulator, and return modeled results. Does not save or execute trades.',
  inputSchema:{type:'object',properties:{period:{type:'string',enum:['FY2025','FY2026']},growth:{type:'number',minimum:-30,maximum:50},margin:{type:'number',minimum:-15,maximum:10},days:{type:'number',minimum:0,maximum:90},capex:{type:'number',minimum:0,maximum:30},borrowing:{type:'number',minimum:0,maximum:30}},required:['period'],additionalProperties:false},
  annotations:{readOnlyHint:false,untrustedContentHint:false},
  execute(input){if(!data)throw Error('Financial data is not ready');if(!input||!['FY2025','FY2026'].includes(input.period))throw Error('Invalid reporting period');const a={};for(const [k,,lo,hi] of sliders){const n=input[k]??0;if(typeof n!=='number'||!Number.isFinite(n)||n<lo||n>hi)throw Error('Invalid '+k);a[k]=n}period=input.period;$('#period').value=period;Object.assign(state,a);nav('simulator');return {period,unit:'USD millions',assumptions:a,results:result,status:'scenario_only'}}
 },{signal:lifecycle.signal})).catch(()=>{});
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
